package local.station.controller;

import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import org.json.*;import java.net.*;import java.io.*;import java.security.*;import java.security.cert.*;import java.util.*;import java.util.concurrent.*;import javax.net.ssl.*;import javax.crypto.*;import javax.crypto.spec.SecretKeySpec;

/** Loopback-only web panel. Station credentials and pinned TLS stay in the Android process. */
public final class LocalPanelService extends Service {
 private ServerSocket server;private String origin,cookie,startCode;private final ExecutorService workers=Executors.newFixedThreadPool(4);private final Handler main=new Handler(Looper.getMainLooper());private volatile boolean closing;private long lastUse=System.currentTimeMillis();
 public static void open(Context context){Intent i=new Intent(context,LocalPanelService.class).setAction("OPEN");if(Build.VERSION.SDK_INT>=26)context.startForegroundService(i);else context.startService(i);}
 @Override public android.os.IBinder onBind(Intent i){return null;}
 @Override public void onCreate(){super.onCreate();cookie=random();startCode=random();String channel="alicekit-local-web";NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel(channel,"Веб-панель на этом устройстве",NotificationManager.IMPORTANCE_LOW));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,channel):new Notification.Builder(this);Intent stop=new Intent(this,LocalPanelService.class).setAction("STOP");PendingIntent action=PendingIntent.getService(this,0,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);b.setContentTitle("AliceKit · локальная веб-панель").setContentText("Работает только на этом устройстве. Нажмите, чтобы остановить.").setSmallIcon(getResources().getIdentifier("studio_icon","drawable",getPackageName())).setContentIntent(action).setOngoing(true);startForeground(42,b.build());try{server=new ServerSocket();server.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0));origin="http://127.0.0.1:"+server.getLocalPort();new Thread(()->{while(!closing)try{Socket s=server.accept();s.setSoTimeout(30000);workers.execute(()->handle(s));}catch(Exception e){if(!closing)stopSelf();}},"alicekit-local-web").start();}catch(Exception e){stopSelf();}main.postDelayed(new Runnable(){public void run(){if(System.currentTimeMillis()-lastUse>30*60000){stopSelf();return;}if(!closing)main.postDelayed(this,60000);}},60000);}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(origin!=null&&i!=null&&"OPEN".equals(i.getAction())){startCode=random();Intent browser=new Intent(Intent.ACTION_VIEW,Uri.parse(origin+"/local/start?code="+startCode)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);try{startActivity(browser);}catch(Exception e){stopSelf();}}return START_NOT_STICKY;}
 private static String random(){byte[] b=new byte[24];new SecureRandom().nextBytes(b);return PublicUpdates.hex(b);}
 private static String line(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();int last=0;for(int i=0;i<8192;i++){int b=in.read();if(b<0)throw new EOFException();if(last=='\r'&&b=='\n'){byte[] raw=out.toByteArray();return new String(raw,0,raw.length-1,"US-ASCII");}out.write(b);last=b;}throw new IOException("Header too long");}
 private static void reply(OutputStream out,int status,String type,byte[] body,String extra)throws Exception{out.write(("HTTP/1.1 "+status+" Reply\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\nContent-Type: "+type+"\r\nContent-Length: "+body.length+"\r\n"+extra+"\r\n").getBytes("US-ASCII"));out.write(body);out.flush();}
 private static void json(OutputStream out,int status,JSONObject body)throws Exception{reply(out,status,"application/json;charset=utf-8",body.toString().getBytes("UTF-8"),"");}
 private static byte[] bounded(InputStream in,int length)throws Exception{if(length<0||length>131072)throw new IOException("Body too large");byte[] b=new byte[length];new DataInputStream(in).readFully(b);return b;}
 private JSONObject connectionRecord()throws Exception{String raw=new SecureStore(this).load();if(raw==null)throw new IOException("Сначала подключите станцию по коду");return new JSONObject(raw);}
 private void handle(Socket socket){try{Socket s=socket;InputStream in=new BufferedInputStream(s.getInputStream());OutputStream out=s.getOutputStream();String[] first=line(in).split(" ");if(first.length!=3||!first[1].startsWith("/")||first[1].startsWith("//"))throw new IOException();Map<String,String> h=new HashMap<>();int headerSize=0;for(;;){String v=line(in);headerSize+=v.length();if(headerSize>16384)throw new IOException();if(v.isEmpty())break;int at=v.indexOf(':');if(at<1)throw new IOException();String key=v.substring(0,at).toLowerCase(Locale.ROOT);if(h.put(key,v.substring(at+1).trim())!=null)throw new IOException("Duplicate header");}if(!("127.0.0.1:"+server.getLocalPort()).equals(h.get("host"))){json(out,403,new JSONObject().put("error","Только локальное соединение"));return;}Uri uri=Uri.parse(first[1]);String path=uri.getPath();if(path.equals("/local/start")&&"GET".equals(first[0])){String code=uri.getQueryParameter("code");synchronized(this){if(startCode==null||!startCode.equals(code)){json(out,403,new JSONObject().put("error","Откройте веб-панель из AliceKit"));return;}startCode=null;}reply(out,303,"text/plain",new byte[0],"Location: /\r\nSet-Cookie: AliceKitLocal="+cookie+"; Path=/; HttpOnly; SameSite=Strict\r\n");return;}
 if(!Arrays.asList(h.getOrDefault("cookie","").split(";\\s*")).contains("AliceKitLocal="+cookie)||h.containsKey("origin")&&!origin.equals(h.get("origin"))){json(out,403,new JSONObject().put("error","Откройте веб-панель из AliceKit"));return;}lastUse=System.currentTimeMillis();if(h.containsKey("transfer-encoding")){json(out,400,new JSONObject().put("error","Используйте загрузку файла с известным размером"));return;}int length=Integer.parseInt(h.getOrDefault("content-length","0"));if(length<0||length>64*1024*1024)throw new IOException("Body limit");
 if(path.startsWith("/local/assets/")){String name=path.substring(14);if(!name.matches("(kontur\\.png|launch-star\\.png|station-max\\.png|onboarding\\.css|manrope\\.ttf)"))throw new IOException();try(InputStream asset=getAssets().open(name)){ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=asset.read(b))!=-1)data.write(b,0,n);reply(out,200,name.endsWith(".css")?"text/css":name.endsWith(".ttf")?"font/ttf":"image/png",data.toByteArray(),"");}return;}
 if(path.equals("/local/")||path.equals("/local")){assetPage(out);return;}
 if(path.equals("/local/state")){JSONObject state=new JSONObject().put("connected",false);try{JSONObject c=connectionRecord();state.put("connected",true).put("host",c.getString("host"));}catch(Exception ignored){}json(out,200,state);return;}
 if(path.equals("/local/discover")&&first[0].equals("POST")){CountDownLatch done=new CountDownLatch(1);List<JSONObject> found=Collections.synchronizedList(new ArrayList<>());main.post(()->new StationDiscovery(this,new StationDiscovery.Listener(){public void found(JSONObject v){synchronized(found){for(int j=0;j<found.size();j++)if(found.get(j).optString("host").equals(v.optString("host"))){found.set(j,v);return;}found.add(v);}}public void finished(){done.countDown();}}).start());done.await(14,TimeUnit.SECONDS);json(out,200,new JSONObject().put("stations",new JSONArray(found)));return;}
 if(path.equals("/local/pair")&&first[0].equals("POST")){JSONObject q=new JSONObject(new String(bounded(in,length),"UTF-8"));pair(StationDiscovery.local(q.getString("host")),q.getString("code"));json(out,200,new JSONObject().put("ok",true));return;}
 if(path.equals("/local/stop")&&first[0].equals("POST")){json(out,200,new JSONObject().put("ok",true));main.postDelayed(()->stopSelf(),250);return;}if(path.equals("/local/alive")){json(out,200,new JSONObject().put("ok",true));return;}JSONObject c;try{c=connectionRecord();}catch(Exception missing){assetPage(out);return;}proxy(out,in,first[0],first[1],length,h,c);
 }catch(Exception failure){try{new SetupJournal(this).add("LOCAL_WEB_ERROR","Ошибка локальной веб-панели",SetupJournal.safe(failure.getMessage()));}catch(Exception ignored){}try{json(socket.getOutputStream(),502,new JSONObject().put("error",SetupJournal.safe(failure.getMessage()==null?"Локальное соединение не завершилось. Проверьте Wi-Fi и сохранённую станцию.":failure.getMessage())));}catch(Exception ignored){}}finally{try{socket.close();}catch(Exception ignored){}}}
 private void assetPage(OutputStream out)throws Exception{try(InputStream input=getAssets().open("web-connect.html")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1)b.write(buffer,0,n);reply(out,200,"text/html;charset=utf-8",b.toByteArray(),"Content-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'\r\n");}}
 private static final class Trust implements X509TrustManager{String pin,seen;Trust(String p){pin=p;}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException();}public void checkServerTrusted(X509Certificate[] c,String a)throws CertificateException{try{c[0].checkValidity();seen=PublicUpdates.hex(MessageDigest.getInstance("SHA-256").digest(c[0].getEncoded()));if(pin!=null&&!MessageDigest.isEqual(pin.getBytes("US-ASCII"),seen.getBytes("US-ASCII")))throw new Exception();}catch(Exception e){throw new CertificateException("Сертификат станции изменился");}}public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}}
 private HttpsURLConnection connect(String host,String path,Trust trust)throws Exception{host=StationDiscovery.local(host);SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,new TrustManager[]{trust},new SecureRandom());HttpsURLConnection c=(HttpsURLConnection)LanNetwork.open(this,new URL("https://"+host+":8789"+path));c.setSSLSocketFactory(ssl.getSocketFactory());final String target=host;c.setHostnameVerifier((h,s)->h.equals(target));c.setConnectTimeout(4500);c.setReadTimeout(25000);c.setInstanceFollowRedirects(false);return c;}
 private static String mac(String key,String value)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key.getBytes("US-ASCII"),"HmacSHA256"));return PublicUpdates.hex(m.doFinal(value.getBytes("UTF-8")));}
 private void pair(String host,String raw)throws Exception{String code=raw.replaceAll("[\\s-]","").toUpperCase(Locale.ROOT);if(!code.matches("[A-Z2-7]{16}"))throw new IOException("Нужен код из 16 знаков с телевизора");Trust t=new Trust(null);HttpsURLConnection probe=connect(host,"/api/pair",t);try{probe.connect();}finally{probe.disconnect();}if(t.seen==null)throw new IOException("Станция не подтвердила сертификат");String nonce=random();HttpsURLConnection c=connect(host,"/api/pair",new Trust(t.seen));try{c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");JSONObject q=new JSONObject().put("nonce",nonce).put("proof",mac(code,nonce+"|"+t.seen)).put("name","AliceKit · локальный браузер");try(OutputStream out=c.getOutputStream()){out.write(q.toString().getBytes("UTF-8"));}if(c.getResponseCode()!=200)throw new IOException("Код не подошёл или истёк");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=c.getInputStream()){byte[] b=new byte[2048];int n;while((n=input.read(b))!=-1){if(bytes.size()+n>8192)throw new IOException();bytes.write(b,0,n);}}JSONObject j=new JSONObject(bytes.toString("UTF-8"));String token=j.getString("token");if(!token.matches("[a-f0-9]{48}")||!MessageDigest.isEqual(mac(code,nonce+"|"+t.seen+"|"+token).getBytes("US-ASCII"),j.getString("proof").getBytes("US-ASCII")))throw new IOException("Подтверждение станции не совпало");new SecureStore(this).save(new JSONObject().put("host",host).put("pin",t.seen).put("token",token).put("clientId",j.getString("clientId")).toString());getSharedPreferences("local-web",0).edit().putBoolean("connectionChanged",true).apply();}finally{c.disconnect();}}
 private void proxy(OutputStream out,InputStream in,String method,String path,int length,Map<String,String> headers,JSONObject record)throws Exception{if(!Arrays.asList("GET","POST","PUT","DELETE","HEAD").contains(method))throw new IOException();HttpsURLConnection c=connect(record.getString("host"),path,new Trust(record.getString("pin")));try{c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer "+record.getString("token"));if(headers.containsKey("content-type"))c.setRequestProperty("Content-Type",headers.get("content-type"));if(length>0){c.setDoOutput(true);c.setFixedLengthStreamingMode(length);try(OutputStream target=c.getOutputStream()){byte[] b=new byte[32768];int left=length;while(left>0){int n=in.read(b,0,Math.min(b.length,left));if(n<0)throw new EOFException();target.write(b,0,n);left-=n;}}}int code=c.getResponseCode();String type=c.getContentType();InputStream source=code<400?c.getInputStream():c.getErrorStream();if(source==null){json(out,code,new JSONObject().put("error","Станция не вернула ответ"));return;}try(InputStream body=source){if(type!=null&&type.startsWith("text/html")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=body.read(b))!=-1){if(bytes.size()+n>2*1024*1024)throw new IOException();bytes.write(b,0,n);}String text=bytes.toString("UTF-8").replace("</body>","<script>addEventListener('DOMContentLoaded',()=>{if(window.stationNativeConnect)stationNativeConnect('000000000000000000000000000000000000000000000000');const a=document.createElement('a');a.href='/local/';a.textContent='Подключение веб-панели';a.style.cssText='position:fixed;right:12px;top:12px;z-index:5000;background:#fff;padding:10px 16px;border-radius:999px;color:#7442b0;font:13px sans-serif;text-decoration:none';document.body.append(a);});setInterval(()=>fetch('/local/alive'),15000)</script></body>");reply(out,code,type,text.getBytes("UTF-8"),"Content-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' blob: data:; media-src 'self' blob: data:; connect-src 'self'; frame-src 'self' about:; object-src 'none'; base-uri 'none'; frame-ancestors 'self'\r\n");}else{out.write(("HTTP/1.1 "+code+" Reply\r\nConnection: close\r\nX-Content-Type-Options: nosniff\r\nCache-Control: no-store\r\nContent-Type: "+(type==null?"application/octet-stream":type)+"\r\n\r\n").getBytes("US-ASCII"));byte[] b=new byte[32768];int n;while((n=body.read(b))!=-1)out.write(b,0,n);out.flush();}}}finally{c.disconnect();}}
 @Override public void onDestroy(){closing=true;main.removeCallbacksAndMessages(null);try{server.close();}catch(Exception ignored){}workers.shutdownNow();stopForeground(true);super.onDestroy();}
}
